import assert from "node:assert/strict";
import { test } from "node:test";
import { deploy } from "../src/cli/deploy.js";

function capture() {
  const lines = [];
  return { lines, log: (line) => lines.push(line) };
}

test("dry run skips the steps and says so", () => {
  const { lines, log } = capture();
  deploy(["--dry-run"], log);
  assert.equal(lines.at(-1), "dry run: 3 steps skipped");
});

test("a full deploy reports every step", () => {
  const { lines, log } = capture();
  deploy([], log);
  assert.deepEqual(lines, ["-> build", "-> upload", "-> activate", "deployed: 3 steps"]);
});

function recordingTarget() {
  const calls = [];
  return {
    calls,
    build: () => calls.push("build"),
    upload: () => calls.push("upload"),
    activate: () => calls.push("activate"),
  };
}

test("a full deploy runs each step against the given target, in order", () => {
  const target = recordingTarget();
  deploy([], () => {}, target);
  assert.deepEqual(target.calls, ["build", "upload", "activate"]);
});

test("dry run touches nothing on the target", () => {
  const target = recordingTarget();
  deploy(["--dry-run"], () => {}, target);
  assert.deepEqual(target.calls, []);
});

test("a target missing a step is rejected", () => {
  const { build, activate } = recordingTarget();
  assert.throws(() => deploy([], () => {}, { build, activate }), /target cannot upload/);
});
